create policy projects_update_owner_or_admin on public.projects for update to authenticated using ((exists (select 1 from public.user_global_role_assignments r where r.user_id=(select auth.uid()) and r.role_code='platform_admin' and r.status='active' and r.effective_from<=now() and (r.effective_to is null or r.effective_to>now())) or (project_manager_id=(select auth.uid()) and exists (select 1 from public.project_memberships m where m.project_id=projects.id and m.user_id=(select auth.uid()) and m.project_role='project_manager' and m.status='active' and m.effective_from<=now() and (m.effective_to is null or m.effective_to>now()))))) with check ((exists (select 1 from public.user_global_role_assignments r where r.user_id=(select auth.uid()) and r.role_code='platform_admin' and r.status='active' and r.effective_from<=now() and (r.effective_to is null or r.effective_to>now())) or (project_manager_id=(select auth.uid()) and exists (select 1 from public.project_memberships m where m.project_id=projects.id and m.user_id=(select auth.uid()) and m.project_role='project_manager' and m.status='active' and m.effective_from<=now() and (m.effective_to is null or m.effective_to>now())))));
grant update (name) on public.projects to authenticated;
